head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gLinkApplSeq;
scwin.gLinkListStatCd;
scwin.g_hdcom_isur_cd;
scwin.g_hdcom_com_abbrv;
scwin.g_hdcom_lm_mkt_tp_cd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.vScrenID = "ULDSTF33010.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
    if (js_market == "9") {
        $c.stf.showObj(panel_mkt_gubun, true);
    } else {
        // 콘트롤 잠그기.
        $c.stf.showObj(panel_mkt_gubun, false);
    }
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};


//20080908 담당팀과 담당자 가져오는 함수
scwin.fn_SetCode = function() {
    //담당팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_DepListLoadComplete = function() {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.fn_list_sync();
};
scwin.fn_list_sync = function() {
    var url = "/LnkDisclsApplCorp.do?method=selectLnkDisclsApplCorp" + "&SEARCH_TYP=APPL_LIST" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&DEP_CD=" + $c.stf.getObjectValue(cmb_TeamList) + "&EMP_NO=" + $c.stf.getObjectValue(cmb_EmpList) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + // 시장구분
        "&LNK_DISCLS_PROCS_STAT_CD=" + $c.stf.getObjectValue(rdo_LNK_DISCLS_PROCS_STAT_CD) + "&SDATE=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&EDATE=" + $c.stf.getObjectValue(edt_EDate); // 종료일자
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setId = function(obj) {
    scwin.gLinkApplSeq = dts_List.getCellData(eval(obj), "LNK_DISCLS_APPL_SEQ");
    scwin.gLinkListStatCd = dts_List.getCellData(eval(obj), "LNK_DISCLS_PROCS_STAT_CD");
    scwin.g_hdcom_isur_cd = dts_List.getCellData(eval(obj), "HDCOM_ISUR_CD");
    scwin.g_hdcom_com_abbrv = dts_List.getCellData(eval(obj), "HDCOM_COM_ABBRV");
    scwin.g_hdcom_lm_mkt_tp_cd = dts_List.getCellData(eval(obj), "HDCOM_LD_MKT_TP_NM");
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "연계공시법인신청목록", "", "8");
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.fn_setId(row);
    if (colid == 'LNK_DISCLS_APPL_TP_NM') {
        await $c.frame.CreateFrame("ULDSTF33011" + row, "/issueinfo/ULDSTF33011.gfm", "연계공시 신청법인 처리", 200, 0, 685, 690 + 30, "window", 0, 0, true);
    } else if (colid == 'LNK_DISCLS_SUBMIT_DDTM') {
        await $c.frame.CreateFrame("ULDSTF33021" + row, "/issueinfo/ULDSTF33021.gfm", "연계공시 신청내역", 200, 70, 950, 560 + 30, "window", 0, 0, true);
    } else if (colid == 'HDCOM_COM_ABBRV') {
        gIsurCd = dts_List.getCellData(row, "HDCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == 'SUBCOM_COM_ABBRV') {
        gIsurCd = dts_List.getCellData(row, "SUBCOM_ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    scwin.fn_DepListLoadComplete();
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	// 로그인사람을 디폴트 선택시

};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_Init();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
};
